import os
import torch


def resume_training_from_checkpoint(checkpoint_path: str) -> dict:
    """
    Load a training checkpoint from the specified path and return its contents.

    Args:
        checkpoint_path: Path to the checkpoint file (.ckpt or .pth)

    Returns:
        Dictionary containing model state, optimizer state, and training metadata

    Raises:
        FileNotFoundError: If the checkpoint file does not exist
        ValueError: If the loaded data is not a dictionary or is missing required keys
        RuntimeError: If the checkpoint file cannot be loaded
    """
    if not os.path.exists(checkpoint_path):
        raise FileNotFoundError(f"Checkpoint file not found: {checkpoint_path}")

    try:
        checkpoint_data = torch.load(checkpoint_path, map_location="cpu", weights_only=False)
    except Exception as e:
        raise RuntimeError(f"Failed to load checkpoint from {checkpoint_path}: {str(e)}")

    if not isinstance(checkpoint_data, dict):
        # If the loaded data is a state_dict (OrderedDict), wrap it in a dict
        if isinstance(checkpoint_data, (dict,)):
            checkpoint_data = {"model_state_dict": checkpoint_data}
        else:
            raise ValueError(
                f"Checkpoint data must be a dictionary, got {type(checkpoint_data).__name__}"
            )

    required_keys = {"model_state_dict", "optimizer_state_dict"}
    # If the checkpoint only contains a model state_dict, add a default optimizer_state_dict
    if "model_state_dict" not in checkpoint_data and "optimizer_state_dict" not in checkpoint_data:
        # Assume the entire dict is the model_state_dict
        checkpoint_data = {"model_state_dict": checkpoint_data, "optimizer_state_dict": {}}

    missing_keys = required_keys - set(checkpoint_data.keys())
    if missing_keys:
        raise ValueError(
            f"Checkpoint is missing required keys: {missing_keys}. "
            f"Expected at least: {required_keys}"
        )

    return checkpoint_data
